import {completeSalaryProgression084} from './complete-salaries-084.js';
import {expandedPayEvidence} from './expanded-pay.js';
import {degreeInventory,degreeInventoryMetadata as meta} from './degree-inventory-data.js';
import {degreeInventoryMatches} from './degree-inventory-matching.js';
import {degreeMatchInput} from './degree-inventory-state.js';
import {escapeHTML as h} from './model.js';
const select=(id,label,items,value)=>`<label>${label}<select id="${id}"><option value="">All</option>${items.map(([k,t])=>`<option value="${h(k)}" ${value===k?'selected':''}>${h(t)}</option>`).join('')}</select></label>`;
export function degreeInventoryPage(s,view={}){
 const result=degreeInventoryMatches(degreeMatchInput(s),degreeInventory,view),limit=view.showAll?result.rows.length:24;
 const fields=[...new Map(degreeInventory.flatMap(o=>o.families).map(f=>[f.id,f.title]))].sort((a,b)=>a[1].localeCompare(b[1]));
 const topics=[...new Set(degreeInventory.flatMap(o=>o.specificInterests.map(x=>x.name)))].sort().map(x=>[x,x]);
 return `<section class="degree-inventory"><a class="text-link" href="#/journey/pathways">← My starting directions</a><div class="page-intro guide-intro"><span class="eyebrow">COLLEGE & GRADUATE CAREERS</span><h1>A wider world of possibilities.</h1><p>${meta.counts.occupations} sourced career profiles. Explore beyond the professions you already know.</p></div><div class="notice"><div><strong>${result.usable?'Connections from your underlying interests.':'Browse freely. Your interests can guide you later.'}</strong><p>${result.usable?'The order compares all six interest scores with official occupational profiles. Reported strengths appear separately. These connections open exploration. After a work preview, reflect on three distinct interests to see whether a new profession qualifies for Top matching. This does not measure aptitude.':result.reason==='open-profile'?'Your answers do not yet form a distinct interest pattern, so we are not ranking professions. Choose a subject or explore the whole inventory.':'Complete the interest assessment to see connections. You can browse every profile now.'}</p></div></div><section class="catalog-filters" aria-label="College career filters"><div class="catalog-filter-row"><label>Search careers or subjects<input id="degree-search" type="search" placeholder="Doctor, law, engineering, biology…" value="${h(view.search||'')}"></label>${select('degree-family','General field',fields,view.family)}${select('degree-education','Degree route',[['college','College · bachelor’s'],['graduate','Graduate / professional']],view.education)}${select('degree-topic','Topic to explore',topics,view.topic)}</div><div class="degree-options"><label><input type="checkbox" id="degree-new" ${view.onlyNew?'checked':''}> New to the guided inventory</label><label><input type="checkbox" id="degree-experienced" ${view.includeExperienced?'checked':''}> Include careers requiring related work experience</label><label><input type="checkbox" id="degree-strong" ${view.strongOnly===false?'':'checked'}> Strong interest connections only</label><label><input type="checkbox" id="degree-strength" ${view.strengthOnly?'checked':''}> Also connected to a reported strength</label><button class="button secondary" data-action="degree-clear">Reset filters</button></div></section><p role="status" id="degree-count">${result.rows.length} ${result.rows.length===1?'career':'careers'}${result.usable?' in this view':' · unranked'} · showing ${Math.min(limit,result.rows.length)}</p><p class="profile-note">A topic filter helps you browse; it is not an assessment answer. Turn off “Strong interest connections only” to investigate careers outside the current broad interest pattern. Related-work requirements refer to typical entry, not whether you could learn the work. Missing experience is not an interest penalty.</p><div class="degree-grid">${result.rows.slice(0,limit).map(o=>degreeCard(o,result.usable)).join('')||'<section class="guide-input-panel"><h2>No careers meet these filters.</h2><p>Try another topic or browse all professions. We keep weaker interest overlap separate instead of filling the list with near matches.</p></section>'}</div>${limit<result.rows.length?'<button class="button secondary" data-action="degree-all">Show all '+result.rows.length+' careers</button>':''}<details class="more-info"><summary>Sources and how to read these connections</summary><p>O*NET31.0 occupational descriptions, six-interest profiles, skills, abilities, knowledge and narrower interest areas; BLS2025–35 typical entry education and experience. ${meta.counts.alreadyGuided} already have a guided profile. ${meta.counts.newDiscovery} are additional exploration profiles. ${meta.counts.withVectors} have complete comparable interest vectors; missing vectors remain browse-only.</p><p>“Strong” uses our existing editorial correlation band, r ≥ 0.608. It describes six-score pattern similarity, not a probability of success. Related strengths are self-reports from your existing experience questions, never a performance test. We do not combine them into an aptitude score. Missing experience does not count as dislike.</p><p>Skills and abilities describe occupational requirements, not measured traits of a student. Some interest descriptors use machine-learning/expert or AI/expert sources. Several specialties share a broader BLS education group. A career’s degree, licensing, cost and first paid stage need separate review before making a plan; this inventory does not assume a salary or lifestyle outcome.</p><a href="${meta.sourceURL}" target="_blank" rel="noopener noreferrer">O*NET source ↗</a> · <a href="${meta.blsSourceURL}" target="_blank" rel="noopener noreferrer">BLS preparation source ↗</a><p>${h(meta.attribution)} <a href="${meta.licenseURL}" target="_blank" rel="noopener noreferrer">CC BY4.0</a></p><a href="./developer/career-coverage-review.html">Why we expanded the inventory →</a></details></section>`;
}
export function degreeCard(o,usable=true){const pay=completeSalaryProgression084(o),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);return `<article class="degree-card"><div class="degree-card-tags"><span>${h(o.educationGroup==='college'?'COLLEGE':'GRADUATE / PROFESSIONAL')}</span><span>${o.guidedId?'Guided profile':'Expanded inventory'}</span></div><h2>${h(o.title)}</h2>${pay?`<p class="degree-pay"><strong>${money(pay.stages[0].amount)} / year</strong><br>Qualified-role estimate · 5-year scenario: ${money(pay.stages[1].amount)}</p><details><summary>Pay source</summary><p>${h(pay.geography)} · ${h(pay.referencePeriod)}</p><p>${h(pay.label)}</p>${pay.sources.map(x=>`<a href="${h(x.url)}" target="_blank" rel="noopener">${h(x.title||x.publisher)} ↗</a>`).join(" · ")}<p>${h(pay.notes.join(" "))}</p></details>`:""}${usable?`<p class="degree-fit"><strong>${h(o.comparable?o.fit.label:'Interest data unavailable')}</strong>${o.r!==null?` · r = ${o.r.toFixed(3)}`:''}</p>`:''}<p>${h(o.summary)}</p><p><strong>Related reported strengths:</strong> ${o.strengths?.length?o.strengths.map(x=>h(x.prompt)).join(' · '):'Not recorded yet.'}</p><p><strong>Preparation:</strong> ${h(o.educationMapping==='broader BLS SOC; O*NET specialty is distinct'?'Broader occupation group: '+o.education+'; specialty requirements can differ.':o.education)}${o.requiresExperience?` · Related work: ${h(o.relatedExperience)}`:''}</p><p><a href="${o.guidedId?'#/journey/profession/'+h(o.guidedId):'#/journey/degree-check/'+h(o.id)}">Explore and reflect on this profession →</a></p><details><summary>Learn about this career</summary><p><strong>Subjects and problems:</strong> ${o.specificInterests.slice(0,5).map(x=>h(x.name)).join(' · ')||'No narrower interest data'}</p><p><strong>Knowledge:</strong> ${o.knowledge.map(x=>h(x.name)).join(' · ')}</p><p><strong>Skills developed and used:</strong> ${o.skills.slice(0,5).map(x=>h(x.name)).join(' · ')}</p><p><strong>Examples of the work:</strong></p><ul>${o.tasks.map(t=>`<li>${h(t.text)}</li>`).join('')}</ul><p>After learning about the work: what surprised you, what appeals, and what would you want to understand before deciding? A new or unfamiliar activity can be worth exploring.</p><p>${h(o.educationBasis)} · ${h(o.educationMapping)}${o.blsSoc?' '+h(o.blsSoc):''}. Confirm the specific program, supervised preparation and licensing requirements for the intended role.</p><a href="${o.url}" target="_blank" rel="noopener noreferrer">Full official profile · ${h(o.soc)} ↗</a> · <a href="${o.educationURL}" target="_blank" rel="noopener noreferrer">Preparation source ↗</a>${o.guidedId?`<p><a href="#/learn/career/${h(o.guidedId)}">Open guided career, pay and planning →</a></p>`:(expandedPayEvidence(o.id)?'<p>A sourced wage planning reference is available in this profession’s comparison. Training costs and the specific first paid job still need review.</p>':'<p>Pay is a planning estimate. Training costs and first-paid-stage lifestyle coverage need separate review.</p>')}</details></article>`;}
